def run_startup_selftest(m4_model, seqs_list=None, meta_list=None):
    """Verify the builder against embedded references. Raise on mismatch."""
    import torch
    fb = sys.modules.get("app.runtime.feature_builder")
    if fb is None:
        from app.runtime import feature_builder as fb

    @torch.no_grad()
    def _run_m4(win):
        x = torch.from_numpy(np.asarray(win, dtype=np.float32)).float().unsqueeze(0)
        recon = m4_model(x)
        mae = torch.mean(torch.abs(x - recon), dim=1).squeeze(0)
        enc = m4_model.encoder
        o1, _ = enc.lstm1(x); o2, (h, c) = enc.lstm2(o1); z = enc.bn(h[-1])
        return mae.cpu().numpy(), z.squeeze(0).cpu().numpy()

    n_fail = 0
    for ref in _REFERENCES:
        win = np.asarray(ref["window"], dtype=np.float32)
        mae, z = _run_m4(win)
        fv = fb.build_m7_features(mae, win, z)
        got = np.array([float(fv[i]) for i in _CHECK_IDX])
        exp = np.array(ref["expected"], dtype=np.float64)
        md = float(np.max(np.abs(got - exp)))
        if md >= _TOL:
            n_fail += 1
            print(f"[selftest] MISMATCH seq={ref['seq_idx']} max_diff={md:.2e} >= tol={_TOL:.0e}")

    if n_fail:
        raise RuntimeError(
            f"[selftest] FAIL — {n_fail}/{len(_REFERENCES)} windows diverged. "
            f"feature_builder no longer matches embedded reference. Aborting startup."
        )
    print(f"[selftest] PASS — {len(_REFERENCES)} windows verified (16 bit-exact cols)")
